public sealed class LibraryOpenOptions {public bool DoubleClickOpen{get;set;}=true;public bool WithSearchResults{get;set;}=true;}
public sealed partial class LibraryWindow {
 LibraryOpenOptions libraryOpenOptions=new();readonly string libraryOpenSettings=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ElansaryWordLibrary","library-open-options.json");string[] lastGeneralWords=Array.Empty<string>();bool streamingGeneral;int directOpenVersion;
 void InitSearchAndOpen(){Title="الأنصاري — بحث مباشر تدريجي وفتح ملفات المكتبة — مراجعة 6";try{if(File.Exists(libraryOpenSettings))libraryOpenOptions=JsonSerializer.Deserialize<LibraryOpenOptions>(File.ReadAllText(libraryOpenSettings))??new();}catch(Exception e){errors.Add(e.Message);}var old=tools.Children.OfType<Button>().Single(b=>b.Content?.ToString()=="بحث عام");int at=tools.Children.IndexOf(old);tools.Children.Remove(old);busyButtons.Remove(old);var search=LocalButton(tools,"بحث عام",SearchIncrementally);tools.Children.Remove(search);tools.Children.Insert(at,search);busyButtons.Add(search);LocalButton(tools,"خيارات فتح الملفات",()=>{ShowLibraryOpenSettings();return Task.CompletedTask;});query.PreviewKeyDown+=async(_,e)=>{if(e.Key!=Key.Enter)return;e.Handled=true;await SearchIncrementally();};
  results.PreviewMouseLeftButtonUp+=(_,e)=>{if(streamingGeneral&&FindRow(e.OriginalSource as DependencyObject) is DisplayRow{Hit:null})e.Handled=true;};results.PreviewKeyDown+=(_,e)=>{if(streamingGeneral&&e.Key==Key.Enter&&results.SelectedItem is DisplayRow{Hit:null})e.Handled=true;};
  library.PreviewMouseDoubleClick+=async(_,e)=>{if(!libraryOpenOptions.DoubleClickOpen)return;string? path=LibraryPath(e.OriginalSource as DependencyObject);if(path==null)return;e.Handled=true;await OpenLibraryFile(path);};string? menuPath=null;var menu=new ContextMenu();var open=new MenuItem{Header="فتح في العارض"};menu.Items.Add(open);library.ContextMenu=menu;library.PreviewMouseRightButtonDown+=(_,e)=>menuPath=LibraryPath(e.OriginalSource as DependencyObject);menu.Opened+=(_,_)=>open.IsEnabled=menuPath!=null;open.Click+=async(_,_)=>{if(menuPath!=null)await OpenLibraryFile(menuPath);};
 }
 string? LibraryPath(DependencyObject? source){while(source!=null){if(source is CheckBox box&&box.ToolTip is string path&&files.Contains(path,StringComparer.OrdinalIgnoreCase))return path;if(ReferenceEquals(source,library))break;source=ReadingParent(source);}return null;}
 async Task SearchIncrementally(){var words=Core.Terms(query.Text);if(words.Length==0){status.Text="اكتب كلمات البحث";return;}var scope=(selected.Count==0?files:files.Where(selected.Contains)).ToArray();if(scope.Length==0){status.Text="أضف ملفات أولًا";return;}await Work(async token=>{lastGeneralWords=words;var watch=Stopwatch.StartNew();long? firstBatch=null;int total=0,checkedFiles=0,failed=0;groups.Clear();var root=new DisplayRow{Text="بحث عام: "+string.Join(" + ",words),Depth=0,Fill=Brushes.Lavender,Contexts=new Dictionary<string,FileResultContext>(StringComparer.OrdinalIgnoreCase)};groups.Add(root);var visible=new ObservableCollection<DisplayRow>{root};results.ItemsSource=visible;var folders=new Dictionary<string,DisplayRow>(StringComparer.OrdinalIgnoreCase);phase=0;fold.Content="طي نتائج المكتبة";fold.IsEnabled=false;streamingGeneral=true;status.Text="جار البحث المباشر؛ ستظهر النتائج تباعًا…";
  try{await Task.Run(async()=>{foreach(string path in scope){token.ThrowIfCancellationRequested();try{var matches=cache.Search(path,words,token);if(matches.Count>0){var hits=matches.Select(h=>new SearchHit{Path=h.Path,Index=h.Index,Text=h.Text,Words=words,Length=h.Length,Ticks=h.Ticks,Offset=words.Min(w=>h.Text.IndexOf(w,StringComparison.OrdinalIgnoreCase))}).ToArray();var context=new FileResultContext(root,hits[0].Path,words,hits);var file=new DisplayRow{Text=$"{Path.GetFileName(path)} ({hits.Length})",Depth=2,Fill=Brushes.LightBlue,Indent=new Thickness(24,2,0,2)};file.Children.AddRange(context.Rows);string dir=Path.GetDirectoryName(path)??"";await Dispatcher.InvokeAsync(()=>{token.ThrowIfCancellationRequested();if(!folders.TryGetValue(dir,out var folder)){folder=new DisplayRow{Text=dir,Depth=1,Fill=Brushes.Honeydew,Indent=new Thickness(12,2,0,2)};folders.Add(dir,folder);root.Children.Add(folder);visible.Add(folder);}folder.Children.Add(file);root.Contexts!.Add(context.Path,context);visible.Add(file);},DispatcherPriority.Background);for(int offset=0;offset<context.Rows.Count;offset+=100){token.ThrowIfCancellationRequested();int start=offset,end=Math.Min(offset+100,context.Rows.Count);await Dispatcher.InvokeAsync(()=>{token.ThrowIfCancellationRequested();for(int i=start;i<end;i++)visible.Add(context.Rows[i]);firstBatch??=watch.ElapsedMilliseconds;},DispatcherPriority.Background);}total+=hits.Length;}}catch(Exception e) when(e is not OperationCanceledException){failed++;string error=path+": "+e.Message;await Dispatcher.InvokeAsync(()=>errors.Add(error),DispatcherPriority.Background);}checkedFiles++;await Dispatcher.InvokeAsync(()=>status.Text=$"بحث مباشر: {checkedFiles}/{scope.Length} ملف — {total} نتيجة — أخطاء: {failed}",DispatcherPriority.Background);}},token);status.Text=$"اكتمل البحث: {total} نتيجة — أول دفعة: {(firstBatch.HasValue?firstBatch.Value.ToString():"—")} ms — الإجمالي: {watch.ElapsedMilliseconds} ms — أخطاء: {failed}";}finally{streamingGeneral=false;fold.IsEnabled=true;RefreshResults();}
 });}
 async Task OpenLibraryFile(string path){int request=++directOpenVersion;int navigationVersion=version;var words=libraryOpenOptions.WithSearchResults?(lastGeneralWords.Length>0?lastGeneralWords.ToArray():Core.Terms(query.Text)):Array.Empty<string>();try{var prepared=await Task.Run(()=>{var doc=cache.Get(path);var root=new DisplayRow{Text="فتح مباشر: "+Path.GetFileName(path)};var hits=new List<SearchHit>();if(words.Length>0)for(int i=0;i<doc.Paragraphs.Length;i++)if(Core.Match(doc.Paragraphs[i],words))hits.Add(new SearchHit{Path=doc.Path,Index=i,Text=doc.Paragraphs[i],Words=words,Length=doc.Length,Ticks=doc.Ticks,Offset=words.Min(w=>doc.Paragraphs[i].IndexOf(w,StringComparison.OrdinalIgnoreCase))});return(doc,context:new FileResultContext(root,doc.Path,words,hits));});if(request!=directOpenVersion||navigationVersion!=version)return;EnsureFullReaderView(false);if(prepared.doc.Paragraphs.Length==0){displayed=prepared.doc;current=null;paragraphs.Clear();viewer.ItemsSource=paragraphs;SetContext(prepared.context);OutlineDocumentChanged(prepared.doc);status.Text="الملف لا يحتوي فقرات نصية";return;}var hit=prepared.context.Rows.FirstOrDefault()?.Hit??new SearchHit{Path=prepared.doc.Path,Index=0,Text=prepared.doc.Paragraphs[0],Words=words,Length=prepared.doc.Length,Ticks=prepared.doc.Ticks};await Show(hit,prepared.context);if(request!=directOpenVersion||displayed?.Path!=prepared.doc.Path||displayed.Length!=prepared.doc.Length||displayed.Ticks!=prepared.doc.Ticks)return;if(libraryOpenOptions.WithSearchResults&&prepared.context.Rows.Count>0)GatherReaderResults();else status.Text=$"تم فتح {Path.GetFileName(path)} مباشرة — نتائج العبارة في الملف: {prepared.context.Rows.Count}";}catch(Exception e){errors.Add(e.ToString());status.Text="تعذر فتح الملف: "+e.Message;}}
 void ShowLibraryOpenSettings(){var window=new Window{Owner=this,Title="خيارات فتح ملفات المكتبة",Width=460,Height=240,FlowDirection=FlowDirection.RightToLeft,WindowStartupLocation=WindowStartupLocation.CenterOwner};var panel=new StackPanel{Margin=new Thickness(15)};window.Content=panel;var direct=new CheckBox{Content="فتح الملف في العارض بالنقر المزدوج على اسمه",IsChecked=libraryOpenOptions.DoubleClickOpen,Margin=new Thickness(4)};var withResults=new CheckBox{Content=new TextBlock{Text="تجميع نتائج عبارة البحث العام داخل الملف المفتوح فقط؛ عند عدم وجود نتائج يظل المستند ظاهرًا",TextWrapping=TextWrapping.Wrap},IsChecked=libraryOpenOptions.WithSearchResults,Margin=new Thickness(4)};panel.Children.Add(direct);panel.Children.Add(withResults);LocalButton(panel,"حفظ",()=>{libraryOpenOptions.DoubleClickOpen=direct.IsChecked==true;libraryOpenOptions.WithSearchResults=withResults.IsChecked==true;Directory.CreateDirectory(Path.GetDirectoryName(libraryOpenSettings)!);File.WriteAllText(libraryOpenSettings,JsonSerializer.Serialize(libraryOpenOptions));window.Close();return Task.CompletedTask;});window.ShowDialog();}
}
